import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong(), q = (int) nextLong();
        HashMap<String, String> value = new HashMap<>(4 * n + 16);
        for (int i = 0; i < n; i++) {
            String k = next(), t = next();
            value.put(k + " " + t, next());
        }
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < q; i++) {
            String k = next(), t = next();
            if (i > 0) out.append(' ');
            out.append(value.get(k + " " + t));
        }
        System.out.println(out);
    }
}

package main

import (
	"io"
	"os"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func nextToken() string {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, q := int(nextInt()), int(nextInt())
	value := make(map[string]string, n)
	for i := 0; i < n; i++ {
		k, t := nextToken(), nextToken()
		value[k+" "+t] = nextToken()
	}
	out := []byte{}
	for i := 0; i < q; i++ {
		k, t := nextToken(), nextToken()
		if i > 0 {
			out = append(out, ' ')
		}
		out = append(out, value[k+" "+t]...)
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
